<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Bot, CheckCircle2, CircleAlert, CircleStop, FileDown, Image, LoaderCircle, MessageSquareText, Plus, Send, Trash2, WandSparkles } from 'lucide-vue-next'
import AppShell from '../components/AppShell.vue'
import MarkdownContent from '../components/MarkdownContent.vue'
import DeliveryFeedbackForm from '../components/DeliveryFeedbackForm.vue'
import { cancelTask, continueTask, deleteTask, fetchConversation, fetchMe, fetchTasks, routeMessage, startTask, taskDownloadUrl } from '../api'
import type { AuthUser, ConversationMessage, TaskInfo } from '../types'
import { appendExecutionStep, appendTimelineMessage, resetConversationTimeline, updateExecutionStep, type ExecutionState, type ConversationTimelineItem } from '../utils/conversationTimeline'

const router = useRouter()
const route = useRoute()
const user = ref<AuthUser>()
const tasks = ref<TaskInfo[]>([])
const selected = ref<TaskInfo>()
const messages = ref<ConversationMessage[]>([])
const timeline = ref<ConversationTimelineItem[]>([])
const prompt = ref('')
const busy = ref(false)
const mode = ref<'chat' | 'pptagent'>('chat')
const web = ref(false)
const images = ref(false)
const error = ref('')
const messagesContainer = ref<HTMLElement>()
const streamingMessageIndex = ref<number>()
const phaseSteps = new Map<string, string>()
const activeToolSteps = new Map<string, string>()
let source: EventSource | undefined

const activeTitle = computed(() => selected.value?.query || '新的创作会话')
const sorted = computed(() => [...tasks.value].sort((a, b) => Date.parse(b.updated_at || b.created_at) - Date.parse(a.updated_at || a.created_at)))
const taskLabel = (status: string) => ({ running: '生成中', completed: '已交付', failed: '需要处理', conversation: '对话中', cancelled: '已取消' } as Record<string, string>)[status] || status

function closeStream() { source?.close(); source = undefined }
function resetTimeline(nextMessages: ConversationMessage[]) { messages.value = nextMessages; timeline.value = resetConversationTimeline(nextMessages); phaseSteps.clear(); activeToolSteps.clear() }
function appendMessage(message: ConversationMessage) { messages.value.push(message); appendTimelineMessage(timeline.value, message); return messages.value.length - 1 }
function appendExecution(label: string, detail = '', state: ExecutionState = 'running') { return appendExecutionStep(timeline.value, label, detail, state) }
function upsertExecution(key: string, label: string, detail = '', state: ExecutionState = 'running') { const existing = phaseSteps.get(key); const id = updateExecutionStep(timeline.value, existing || '', label, detail, state); phaseSteps.set(key, id); return id }
function beginTool(name = '', detail = '') { activeToolSteps.set(name || 'unknown', appendExecution(toolLabel(name), detail || '正在调用')) }
function finishTool(name = '', detail = '', state: ExecutionState = 'success') { const key = name || 'unknown'; const id = activeToolSteps.get(key); if (id) updateExecutionStep(timeline.value, id, toolLabel(name), detail || '已完成', state); else activeToolSteps.set(key, appendExecution(toolLabel(name), detail || '已完成', state)); activeToolSteps.delete(key) }
function phaseLabel(phase = '') { return ({ analysis: '分析请求', answer: '组织回答' } as Record<string, string>)[phase] || '处理任务' }
function toolLabel(name = '') { return ({ search: '联网检索', search_images: '图片搜索' } as Record<string, string>)[name] || name || '调用工具' }
function stickToLatestMessage() { const container = messagesContainer.value; if (!container || container.scrollHeight - container.scrollTop - container.clientHeight > 96) return; container.scrollTop = container.scrollHeight }
function appendAssistantChunk(content: string) { if (!content) return; const index = streamingMessageIndex.value; const message = index === undefined ? undefined : messages.value[index]; if (message?.role === 'assistant') message.content += content; else streamingMessageIndex.value = appendMessage({ role: 'assistant', content, timestamp: new Date().toISOString() }); nextTick(stickToLatestMessage) }
async function loadTasks() { tasks.value = await fetchTasks() }
async function select(task: TaskInfo) { closeStream(); streamingMessageIndex.value = undefined; selected.value = task; error.value = ''; const session = await fetchConversation(task.id); const sessionMessages = [...(session.messages || [])]; if (session.full_answer && !sessionMessages.some(message => message.role === 'assistant' && message.content === session.full_answer)) sessionMessages.push({ role: 'assistant', content: session.full_answer, timestamp: '' }); resetTimeline(sessionMessages); if (session.conversation_streaming || task.status === 'running') openStream(task.id, session.replay_after_event_id || session.latest_event_id || 0) }
function openStream(id: string, after = 0) { closeStream(); busy.value = true; source = new EventSource(`/api/tasks/${id}/stream${after ? `?after_id=${after}` : ''}`); const receive = (event: MessageEvent) => consume(event.data); for (const name of ['answer', 'answer_end', 'system_step', 'tool_call', 'tool_result', 'progress', 'runtime_event', 'file_ready', 'thumbnail_ready', 'error', 'complete', 'continue_complete', 'continue_queued', 'conversation_complete']) source.addEventListener(name, receive); source.onerror = () => { closeStream(); busy.value = false; appendExecution('连接已结束', '已从会话快照恢复', 'success'); refreshSelected() } }
function consume(raw: string) { try { const data = JSON.parse(raw) as { type?: string; content?: string; error?: string; message?: string; phase?: string; phase_detail?: string; tool_name?: string; runtime_event?: { kind?: string; name?: string; detail?: string; status?: string } }; if (data.type === 'answer') appendAssistantChunk(data.content || ''); else if (data.type === 'error') { error.value = data.error || '任务出现错误'; appendExecution('生成遇到错误', error.value, 'error') } else if (data.type === 'runtime_event') { const event = data.runtime_event; const state: ExecutionState = event?.status === 'error' || event?.status === 'failed' ? 'error' : event?.status === 'ok' ? 'success' : 'running'; appendExecution(event?.name || event?.kind || '处理任务', event?.detail || '', state) } else if (data.type === 'tool_call') beginTool(data.tool_name, data.phase_detail || data.message || '正在调用'); else if (data.type === 'tool_result') finishTool(data.tool_name, data.error || data.phase_detail || data.message || '已完成', data.error ? 'error' : 'success'); else if (data.type === 'system_step') upsertExecution(`phase:${data.phase || 'system'}`, phaseLabel(data.phase), data.phase_detail || data.message || '正在推进', 'running'); else if (data.type === 'progress') appendExecution(data.phase_detail || data.phase || '推进生成', data.message || ''); else if (data.type === 'file_ready') appendExecution('演示文件已生成', '可以下载并继续修改', 'success'); else if (['answer_end', 'complete', 'continue_complete', 'conversation_complete'].includes(data.type || '')) { busy.value = false; closeStream(); streamingMessageIndex.value = undefined; upsertExecution('phase:answer', '组织回答', '已完成', 'success'); appendExecution(data.type === 'conversation_complete' ? '回答完成' : '生成阶段结束', '', 'success'); refreshSelected() } } catch { /* Ignore SSE keepalive frames. */ } }
async function refreshSelected() { await loadTasks(); if (!selected.value) return; const fresh = tasks.value.find(task => task.id === selected.value?.id); if (fresh) selected.value = fresh }
async function submit() { const text = prompt.value.trim(); if (!text || busy.value) return; error.value = ''; streamingMessageIndex.value = undefined; appendMessage({ role: 'user', content: text, timestamp: new Date().toISOString() }); prompt.value = ''; busy.value = true; await nextTick(stickToLatestMessage); try { if (selected.value?.status === 'completed' || selected.value?.status === 'failed' || selected.value?.status === 'cancelled') { appendExecution('继续处理任务', '正在提交新的修订请求'); const result = await continueTask(selected.value.id, text); openStream(result.task_id, result.after_event_id || 0); return } const result = await routeMessage(text, selected.value?.id || '', mode.value, web.value, images.value); await loadTasks(); selected.value = tasks.value.find(task => task.id === result.task_id) || selected.value; if (mode.value === 'pptagent') { appendExecution('已确认 PPT 生成', '直接启动规划与交付'); const started = await startTask(result.task_id); selected.value = started; openStream(started.id); return } if (result.reply) appendMessage({ role: 'assistant', content: result.reply, timestamp: new Date().toISOString() }); openStream(result.task_id, result.after_event_id || 0) } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法提交这条消息'; busy.value = false; streamingMessageIndex.value = undefined; appendExecution('提交失败', error.value, 'error') } }
async function remove(id: string) { if (!confirm('删除这个会话及其交付文件？')) return; await deleteTask(id); if (selected.value?.id === id) { selected.value = undefined; resetTimeline([]) }; await loadTasks() }
async function stop() { if (!selected.value) return; await cancelTask(selected.value.id); closeStream(); busy.value = false; appendExecution('任务已停止', '', 'success'); await refreshSelected() }
function newConversation() { closeStream(); streamingMessageIndex.value = undefined; selected.value = undefined; resetTimeline([]); error.value = ''; prompt.value = String(route.query.brief || ''); router.replace({ query: {} }) }
onMounted(async () => { try { user.value = await fetchMe(); await loadTasks(); const brief = String(route.query.brief || ''); const wanted = String(route.query.task || ''); if (brief) newConversation(); else { const target = tasks.value.find(task => task.id === wanted) || tasks.value[0]; if (target) await select(target) } } catch (cause) { error.value = cause instanceof Error ? cause.message : '加载工作台失败' } }); onBeforeUnmount(closeStream); watch(() => route.query.brief, value => { if (value) newConversation() })
</script>

<template>
  <AppShell title="创作工作台" subtitle="对话、规划与交付在同一条轨迹里" :email="user?.email" :guest="user?.is_guest" @new="newConversation">
    <template #header><button class="compose-link" @click="router.push('/compose')"><WandSparkles :size="16" />编排页面</button></template>
    <div class="workbench"><aside class="conversations"><div class="conversation-head"><span>你的会话</span><button @click="newConversation" aria-label="新建会话"><Plus :size="17" /></button></div><div class="task-list"><button v-for="task in sorted" :key="task.id" class="task-row" :class="{selected:task.id===selected?.id}" @click="select(task)"><span class="status-dot" :class="task.status" /><span class="task-info"><b>{{ task.query || '未命名会话' }}</b><small>{{ taskLabel(task.status) }} · {{ task.total_count ? `${task.done_count}/${task.total_count} 页` : '对话' }}</small></span><Trash2 :size="14" class="delete" @click.stop="remove(task.id)" /></button><p v-if="!tasks.length" class="empty-list">还没有会话。<br>从右侧写下第一个想法。</p></div></aside><section class="canvas"><header class="canvas-head"><div><span class="canvas-kicker">{{ selected ? taskLabel(selected.status) : '准备就绪' }}</span><h2>{{ activeTitle }}</h2></div><div v-if="selected" class="canvas-actions"><button v-if="selected.status==='running'" class="outline-button" @click="stop"><CircleStop :size="15" />停止</button><a v-for="file in selected.files" :key="file" class="download" :href="taskDownloadUrl(selected.id,file)"><FileDown :size="15" />下载</a></div></header><div ref="messagesContainer" class="messages" aria-live="polite" aria-atomic="false"><div v-if="!timeline.length" class="blank-canvas"><span><Bot :size="25" /></span><h3>从一个问题开始。</h3><p>可以让它解释、梳理资料，或直接开始一份演示。明确需求会让成稿更接近你的表达。</p><div><button @click="prompt='为一场产品发布会规划 8 页叙事'">规划一份发布会演示</button><button @click="prompt='总结这份资料的核心观点'">先梳理一个主题</button></div></div><template v-for="item in timeline" :key="item.id"><article v-if="item.type==='message'" class="message" :class="item.message.role"><div class="message-label">{{ item.message.role==='user'?'你':'Deckform' }}</div><MarkdownContent :content="item.message.content" :streaming="busy && item.message===messages[streamingMessageIndex ?? -1]" /></article><section v-else class="execution-node" :class="item.state" :role="item.state==='error'?'alert':'status'" :aria-label="`${item.label}：${item.detail || item.state}`"><span class="execution-marker"><LoaderCircle v-if="item.state==='running'" :size="15" /><CircleAlert v-else-if="item.state==='error'" :size="15" /><CheckCircle2 v-else :size="15" /></span><div><span class="execution-label">执行步骤</span><b>{{ item.label }}</b><p v-if="item.detail">{{ item.detail }}</p></div></section></template><DeliveryFeedbackForm v-if="selected?.status==='completed'" :task-id="selected.id" :feedback="selected.feedback" @saved="task => { selected = task; loadTasks() }" /><div v-if="busy" class="thinking"><LoaderCircle :size="17" />正在等待下一步</div></div><form class="composer" novalidate @submit.prevent="submit"><div class="modebar"><button type="button" :class="{on:mode==='chat'}" @click="mode='chat'"><MessageSquareText :size="14" />对话</button><button type="button" :class="{on:mode==='pptagent'}" @click="mode='pptagent'"><WandSparkles :size="14" />PPT 生成</button><label><input v-model="web" type="checkbox">联网资料</label><label><input v-model="images" type="checkbox"><Image :size="13" />图片参考</label></div><div class="composer-input"><textarea v-model="prompt" class="resize-none" rows="2" :disabled="busy" placeholder="写下你想完成的事…" @keydown.enter.exact.prevent="submit" /><button type="submit" :disabled="busy||!prompt.trim()"><Send :size="18" /></button></div><p v-if="error" class="inline-error">{{ error }}</p></form></section></div>
  </AppShell>
</template>

<style scoped>
.compose-link{margin-left:auto;display:flex;align-items:center;gap:6px;border:1px solid rgba(162,210,212,.24);border-radius:6px;padding:8px 10px;color:#bfe6df;background:#0e2b37;font-size:12px}.workbench{min-height:0;flex:1;display:grid;grid-template-columns:254px minmax(0,1fr);overflow:hidden}.conversations{min-height:0;display:flex;flex-direction:column;border-right:1px solid rgba(213,235,245,.1);background:#0b1a27}.conversation-head{display:flex;align-items:center;justify-content:space-between;padding:20px 16px 14px;color:#bdd0d9;font-size:12px}.conversation-head button{display:grid;place-items:center;width:27px;height:27px;color:#97eee0;background:#15414a;border:0;border-radius:5px}.task-list{min-height:0;overflow:auto;padding:0 8px 16px}.task-row{position:relative;width:100%;display:flex;align-items:center;gap:8px;padding:11px 7px;border:0;border-radius:6px;color:#aabec7;background:transparent;text-align:left}.task-row:hover,.task-row.selected{background:#15303e;color:#eef8f6}.task-info{min-width:0;flex:1}.task-info b,.task-info small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-info b{font-size:13px;font-weight:600}.task-info small{margin-top:3px;color:#76919e;font-size:11px}.status-dot{width:7px;height:7px;border-radius:50%;background:#718895}.status-dot.running{background:#66e1ca;box-shadow:0 0 0 4px rgba(102,225,202,.1)}.status-dot.completed{background:#74c5ee}.status-dot.failed{background:#e98e89}.delete{opacity:0;color:#e9a3a0}.task-row:hover .delete{opacity:1}.empty-list{padding:18px 8px;color:#647d89;font-size:12px;line-height:1.7}.canvas{min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:#0c1d2a}.canvas-head{display:flex;justify-content:space-between;gap:20px;padding:17px 30px;border-bottom:1px solid rgba(213,235,245,.1)}.canvas-kicker{font:500 10px 'DM Mono',monospace;color:#71d6c4;letter-spacing:.08em}.canvas-head h2{max-width:690px;margin:4px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:700 18px 'Noto Serif SC',serif}.canvas-actions{display:flex;align-items:center;gap:8px}.outline-button,.download{display:flex;align-items:center;gap:5px;padding:7px 9px;border:1px solid #466473;border-radius:5px;color:#b3cbd0;background:transparent;font-size:12px}.download{color:#082b36;background:#72e0c9;border-color:#72e0c9}.messages{min-height:0;overflow:auto;padding:27px max(25px,7%)}.blank-canvas{max-width:570px;margin:8vh auto;text-align:center}.blank-canvas>span{display:grid;place-items:center;width:53px;height:53px;margin:auto;color:#63ddc7;background:#123b48;border-radius:16px 16px 4px 16px}.blank-canvas h3{margin:19px 0 9px;font:700 28px 'Noto Serif SC',serif}.blank-canvas p{margin:auto;max-width:450px;color:#8da4af;font-size:14px;line-height:1.8}.blank-canvas div{display:flex;justify-content:center;gap:8px;margin-top:25px}.blank-canvas button{border:1px solid #315260;border-radius:5px;padding:8px 10px;color:#b6cbd2;background:#102a36;font-size:12px}.message{max-width:760px;margin:0 auto 22px;padding:18px 20px;border-radius:3px 13px 13px 13px}.message.user{max-width:650px;margin-right:0;color:#d9edf0;background:#173846}.message.assistant{color:#243d45;background:#f0f1e9}.message-label{margin-bottom:10px;font:500 10px 'DM Mono',monospace;letter-spacing:.08em;color:#56928b}.message.user .message-label{color:#94d7ce}.execution-node{position:relative;display:grid;grid-template-columns:25px minmax(0,1fr);gap:9px;max-width:760px;margin:0 auto 15px;padding:3px 0 3px 1px;color:#93b3b6}.execution-node::before{position:absolute;top:0;bottom:-15px;left:8px;width:1px;background:rgba(111,201,195,.18);content:''}.execution-marker{z-index:1;display:grid;place-items:center;width:17px;height:17px;color:#79c6e5;background:#0c1d2a}.execution-node.running .execution-marker{color:#72e2cb}.execution-node.error .execution-marker{color:#ef9892}.execution-marker svg{animation:spin 1s linear infinite}.execution-node:not(.running) .execution-marker svg{animation:none}.execution-label{display:block;margin:0 0 2px;color:#5e908c;font:500 9px 'DM Mono',monospace;letter-spacing:.08em;text-transform:uppercase}.execution-node b{display:block;color:#c5d9d9;font-size:12px;font-weight:600}.execution-node p{margin:2px 0 0;color:#7898a1;font-size:12px;line-height:1.45}.execution-node.error p{color:#e7a19b}.thinking{display:flex;gap:8px;align-items:center;max-width:760px;margin:0 auto;color:#8cd9ca;font-size:13px}.thinking svg{animation:spin 1s linear infinite}.composer{padding:12px 30px 18px;border-top:1px solid rgba(213,235,245,.1);background:#0c1d2a}.modebar{display:flex;align-items:center;gap:5px;margin:0 0 7px}.modebar button,.modebar label{display:flex;align-items:center;gap:4px;border:0;padding:5px 7px;color:#76929d;background:transparent;font-size:11px}.modebar button.on{color:#85ebd8;background:#123b47;border-radius:4px}.modebar label{margin-left:5px}.modebar input{accent-color:#5edbc5}.composer-input{display:grid;grid-template-columns:1fr 43px;gap:8px;padding:8px;background:#eff2e9;border-radius:8px}.composer textarea{width:100%;min-height:39px;resize:none;padding:6px 8px;border:0;outline:0;color:#18333d;background:transparent;line-height:1.5}.composer-input button{display:grid;place-items:center;align-self:end;height:39px;border:0;border-radius:5px;color:#f3fbf6;background:#0e6670}.composer-input button:disabled{opacity:.4}.inline-error{margin:7px 0 0;color:#f4aaa1;font-size:12px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:850px){.workbench{grid-template-columns:1fr}.conversations{display:none}.canvas-head,.composer{padding-left:18px;padding-right:18px}.messages{padding:22px 18px}.message{padding:15px}.modebar label{display:none}}
</style>
